oxy_webhelp_navlinks = {"recovering_ad_forest-d39536e58443":{"topics":[{"title":"Comparison of AD recovery methods","shortdesc":"<p class=\"shortdesc\">Compare the three recovery methods available for Active Directory recovery to choose         the option that best matches your recovery scenario.<\/p>","href":"adds\/ad_recovery_methods_comparison.html","attributes":{"data-id":"ad_recovery_methods_comparison"},"menu":{"hasChildren":false},"tocID":"ad_recovery_methods_comparison-d39536e58457","topics":[]},{"title":"Identity-first recovery for AD forest","shortdesc":"<p class=\"shortdesc\">Rubrik recommends the identity-first recovery method to recover an Active Directory         forest. <span class=\"ph\">RSC<\/span> extracts only the identity data from a domain controller         snapshot and reintroduces it into a fresh Windows target, decoupling the recovery from the         source operating system.<\/p>","href":"adds\/ad_identity_first_recovery.html","attributes":{"data-id":"ad_identity_first_recovery"},"menu":{"hasChildren":false},"tocID":"ad_identity_first_recovery-d39536e58468","topics":[]},{"title":"Identity-first recovery prerequisites","shortdesc":"<p class=\"shortdesc\">Information about the prerequisites for recovering an Active Directory forest using         Identity-first recovery.<\/p>","href":"adds\/ad_identity_first_recovery_prereq.html","attributes":{"data-id":"ad_identity_first_recovery_prereq"},"menu":{"hasChildren":false},"tocID":"ad_identity_first_recovery_prereq-d39536e58482","topics":[]},{"title":"AD alternate host recovery compatibility checks","shortdesc":"<p class=\"shortdesc\">Information about the compatibility checks that <span class=\"ph\">RSC<\/span> performs on the         target host before recovering a domain controller to an alternate host.<\/p>","href":"adds\/ad_alternate_host_compatibility_checks.html","attributes":{"data-id":"ad_alternate_host_compatibility_checks"},"menu":{"hasChildren":false},"tocID":"ad_alternate_host_compatibility_checks-d39536e58493","topics":[]},{"title":"AD forest recovery health checks","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> runs several integrity checks during an Active Directory forest         recovery to verify the health of the restored forest and its successful         restoration.<\/p>","href":"adds\/ad_forest_recovery_health_checks.html","attributes":{"data-id":"ad_forest_recovery_health_checks"},"menu":{"hasChildren":false},"tocID":"ad_forest_recovery_health_checks-d39536e58507","topics":[]},{"title":"AD alternate host recovery prerequisites","shortdesc":"<p class=\"shortdesc\">Information about Microsoft-recommended prerequisites that you must fulfill to         successfully recover domain controllers or domains in an Active Directory         forest.<\/p>","href":"adds\/ad_ahr_prereq.html","attributes":{"data-id":"ad_ahr_prereq"},"menu":{"hasChildren":false},"tocID":"ad_ahr_prereq-d39536e58520","topics":[]},{"title":"AD host promotion prerequisites","shortdesc":"<p class=\"shortdesc\">Information about the requirements for promoting a vanilla Windows host to an Active         Directory domain controller using replication or Install from Media.<\/p>","href":"adds\/ad_host_promotion_prereqs.html","attributes":{"data-id":"ad_host_promotion_prereqs"},"menu":{"hasChildren":false},"tocID":"ad_host_promotion_prereqs-d39536e58531","topics":[]},{"title":"Prerequisites for AD forest bare-metal recovery","shortdesc":"<p class=\"shortdesc\">Information about the specific requirements for recovering domains in an Active         Directory forest using the bare-metal recovery method.<\/p>","href":"adds\/adfr_bmr_prereq.html","attributes":{"data-id":"adfr_bmr_prereq"},"menu":{"hasChildren":false},"tocID":"adfr_bmr_prereq-d39536e58542","topics":[]},{"title":"Tracking AD forest recovery","shortdesc":"<p class=\"shortdesc\">After initiating Active Directory forest recovery, <span class=\"ph\">RSC<\/span> provides a         tracker that details each step, the status, and any errors or warnings. It also outlines the         next course of action required to complete the recovery process.<\/p>","href":"adds\/tracking_ad_forest_recovery.html","attributes":{"data-id":"tracking_ad_forest_recovery"},"menu":{"hasChildren":false},"tocID":"tracking_ad_forest_recovery-d39536e58553","topics":[]},{"title":"AD forest recovery advanced settings options","shortdesc":"<p class=\"shortdesc\">While initiating Active Directory forest recovery process, <span class=\"ph\">RSC<\/span>         provides an option to configure the advanced settings for Windows time service, global         catalog servers, and reset KRBTGT password.<\/p>","href":"adds\/ad_forest_recovery_advanced_settings_options_.html","attributes":{"data-id":"ad_forest_recovery_advanced_settings_options_"},"menu":{"hasChildren":false},"tocID":"ad_forest_recovery_advanced_settings_options_-d39536e58567","topics":[]},{"title":"AD forest recovery using replicated snapshots","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides the flexibility and robustness to recover Active         Directory forest using replicated snapshots in the event of a disaster or ransomware         attack.<\/p>","href":"adds\/ad_forest_recovery_using_replicated_snapshots.html","attributes":{"data-id":"ad_forest_recovery_using_replicated_snapshots"},"menu":{"hasChildren":false},"tocID":"ad_forest_recovery_using_replicated_snapshots-d39536e58582","topics":[]},{"title":"Configuring a Rubrik cluster as primary for a Windows host","shortdesc":"<p class=\"shortdesc\">Configure Windows host settings to set a Rubrik cluster as the primary cluster for an         AD domain controller host.<\/p>","href":"adds\/configuring_rbrk_clstr_primry_win_host.html","attributes":{"data-id":"configuring_rbrk_clstr_primry_win_host"},"menu":{"hasChildren":false},"tocID":"configuring_rbrk_clstr_primry_win_host-d39536e58595","topics":[]},{"title":"Re-establishing AD forest protection after recovery","shortdesc":"<p class=\"shortdesc\">After completing an Active Directory Forest Recovery and deciding to promote the         recovered forest to your production environment, re-establish protection by removing old         metadata, cleaning up registry entries, and reinstalling RBS. For test recoveries, no action         is required as <span class=\"ph\">RSC<\/span> continues to protect your original production         forest.<\/p>","href":"adds\/reestablishing_ad_forest_protection.html","attributes":{"data-id":"reestablishing_ad_forest_protection"},"menu":{"hasChildren":false},"tocID":"reestablishing_ad_forest_protection-d39536e58606","topics":[]}]}};